// busPlan() exactly as it was at build 647 (before BUS INTO BUS, 19 Nov), kept so tests/bus-into-bus.test.js can prove the new plan
// is identical on every shape except the newly working one. A string, run in a vm with chainsFeed / NT / int / S around it.
module.exports = "let busPlanH = null, busPlanVal = null;\nfunction busPlan(){\n  const d = S.chainPatch, ok = !!(d && d.format === 'chains.patch' && Array.isArray(d.modules));\n  let h = ok ? 7 : 0; const mx = v => { h = (h * 31 + v) | 0; }, ms = x => { x = String(x); for (let i = 0; i < x.length; i++) mx(x.charCodeAt(i)); };\n  if (ok){ for (const m of d.modules) if (m){ ms(m.id); const k = m.type === 'trackIn' ? 1 : m.type === 'chainOut' ? 2 : 3; mx(k); if (k < 3) mx(+(m.params && m.params.track) | 0); if (k === 1) mx(+(m.params && m.params.pre) ? 5 : 4); }\n    for (const c of d.cables || []) if (c && c.from && c.to){ ms(c.from[0]); mx(59); ms(c.to[0]); } }\n  for (let t = 0; t < NT; t++) mx(S.chainOn && S.chainOn[t] ? 2 : 1);\n  if (busPlanVal && busPlanH === h) return busPlanVal;\n  busPlanH = h;\n  const feeds = new Map(), targets = new Map(), pure = new Set(), pre = new Set(), P = busPlanVal = {feeds, targets, pure, pre, loop:false};   // pre: PRE SENDS\n  if (!ok) return P;\n  const by = new Map(); for (const m of d.modules) if (m && m.id != null) by.set(m.id, m);\n  const nx = new Map(); for (const c of d.cables || []) if (c && c.from && c.to){ const a = c.from[0]; if (!nx.has(a)) nx.set(a, []); nx.get(a).push(c.to[0]); }\n  const trk = m => { const k = int(m.params && m.params.track, 1); return k >= 1 && k <= NT ? k - 1 : -1; };\n  // OWNER (25 Oct): a Chain Out for a track that brings its own sound in (it has a Track In of its own) is that track's own\n  // output, not a bus. A bus is a track the patch feeds from elsewhere: a Chain Out with no Track In beside it. Without this,\n  // a send (4 and 5 keep their outs and also feed 6) read the other track's out as a bus, which the loop check then skipped,\n  // so the mixer showed a bus that only half worked.\n  const ownIn = new Set();\n  for (const m of by.values()) if (m.type === 'trackIn'){ const k = trk(m); if (k >= 0) ownIn.add(k); }\n  const adj = new Map(), reaches = (a, b) => { const seen = new Set([a]), w = [a]; while (w.length){ const x = w.pop(); if (x === b) return true; for (const y of adj.get(x) || []) if (!seen.has(y)){ seen.add(y); w.push(y); } } return false; };\n  for (const m of by.values()){\n    if (m.type !== 'trackIn') continue; const t = trk(m); if (t < 0 || !(S.chainOn && S.chainOn[t])) continue;\n    const seen = new Set([m.id]), w = [m.id], outs = new Set();\n    while (w.length){ const id = w.pop(), x = by.get(id); if (x && x.type === 'chainOut'){ const o = trk(x); if (o >= 0) outs.add(o); }\n      for (const y of nx.get(id) || []) if (!seen.has(y)){ seen.add(y); w.push(y); } }\n    let fed = false;\n    for (const b of [...outs].sort((a, c) => a - c)){\n      if (b === t || ownIn.has(b) || !chainsFeed(b)) continue;   // its own out, or not a bus (see ownIn above)\n      if (reaches(b, t)){ P.loop = true; continue; }\n      if (!adj.has(t)) adj.set(t, []); adj.get(t).push(b); fed = true;\n      if (!feeds.has(b)) feeds.set(b, []); feeds.get(b).push(t);\n      if (!targets.has(t)) targets.set(t, []); targets.get(t).push(b);\n    }\n    if (fed && !outs.has(t)) pure.add(t);\n    if (fed && +(m.params && m.params.pre)) pre.add(t);   // PRE SENDS (27 Oct): its Track In's Bus send is \"Before its fader\"\n  }\n  for (const v of feeds.values()) v.sort((a, b) => a - b);\n  return P;\n}\n";
